package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    @Test
    public void nextTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        assertEquals(1, stockSpan.next(10));
        assertEquals(1, stockSpan.next(5));
        assertEquals(2, stockSpan.next(10));
    }

    @Test
    public void calculateSpansTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10, 5, 10};
        int[] expected = {1, 1, 2};
        assertArrayEquals(expected, stockSpan.calculateSpans(prices));
    }

}
```

This code provides two unit tests for the `next` and `calculateSpans` methods of the `OnlineStockSpan` class. The `nextTest` method tests the `next` method with three different prices and asserts that the returned values are correct. The `calculateSpansTest` method tests the `calculateSpans` method with a sample array of prices and asserts that the returned array of spans is correct.
